#!/usr/bin/env node
/**
 * tests/adversarial-gtv-m2-challenger.js
 * 
 * Empirical Adversarial Challenge Test Harness — Milestone 2 (R2: Hero Presentation & 16:9 Card Proportions)
 * Agent: challenger_gtv_m2_1
 * 
 * Conducts adversarial stress-testing, boundary analysis, and chaos fuzzing on:
 * - Suite 1: CardFactory.createPosterCard Malformed Inputs & Security Fuzzing
 * - Suite 2: 16:9 Card Proportions (352x198px) & 262px .strip Overflow Stress
 * - Suite 3: GPU translateX Calculations & Horizontal Scroll Mechanics
 * - Suite 4: Carousel Navigation, stepHero & 300ms Debounce Timer under Rapid D-Pad Bursts
 * - Suite 5: Zero DOM Sinks & Architectural Invariants (Service SHA-256, Zero innerHTML/outerHTML)
 */

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved:', e1.message);
      process.exit(1);
    }
  }
}

// 2. Terminal Styling
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureDetails = [];

async function check(suiteId, checkId, title, testFn) {
  totalChecks++;
  const label = `[${suiteId}.${checkId}] ${title}`;
  const start = Date.now();
  try {
    await testFn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
    console.log(`      ${C.red}Error: ${err.message}${C.reset}`);
    failureDetails.push({ label, error: err.message, stack: err.stack });
  }
}

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Adversarial assertion failed');
  }
}

/**
 * Helper to create isolated DOM window with index.html and scripts loaded
 */
function createTestEnvironment(initialUrl = 'http://localhost/#home') {
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const homePath = path.resolve(__dirname, '../app/js/views/home.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: initialUrl,
    runScripts: 'outside-only',
    pretendToBeVisual: true
  });
  const { window } = dom;

  if (!window.Element.prototype.scrollIntoView) {
    window.Element.prototype.scrollIntoView = function () {};
  }

  const configCode = fs.readFileSync(configPath, 'utf8');
  const homeCode = fs.readFileSync(homePath, 'utf8');
  const appCode = fs.readFileSync(appPath, 'utf8');

  window.eval(configCode);
  window.eval(homeCode);
  window.eval(appCode);

  return { dom, window, app: window.CinejoyApp, CardFactory: window.CardFactory, HomeCtrl: window.HomeViewController };
}

// -----------------------------------------------------------------------------
// SUITE 1: CardFactory.createPosterCard Malformed Inputs & Security Fuzzing
// -----------------------------------------------------------------------------
async function runSuite1() {
  console.log(`\n${C.bold}${C.cyan}▶ SUITE 1: CardFactory.createPosterCard Malformed Inputs & Security Fuzzing${C.reset}`);
  const { window, CardFactory } = createTestEnvironment();

  await check('S1', '01', 'Handling null and undefined input items returns comment node without throwing', () => {
    const cardNull = CardFactory.createPosterCard(null, 'shelf-test', 0);
    assert(cardNull !== null && cardNull !== undefined, 'CardFactory(null) returned falsy');
    assert(cardNull.nodeType === 8, `Expected comment node (nodeType 8), got ${cardNull.nodeType}`);
    assert(cardNull.nodeValue === 'empty-card', `Expected 'empty-card', got ${cardNull.nodeValue}`);

    const cardUndef = CardFactory.createPosterCard(undefined, 'shelf-test', 1);
    assert(cardUndef.nodeType === 8, 'Expected comment node for undefined');
  });

  await check('S1', '02', 'Handling completely empty object {} applies safe defaults without throwing', () => {
    const card = CardFactory.createPosterCard({}, 'shelf-empty', 0);
    assert(card.nodeType === 1, 'Expected element node');
    assert(card.getAttribute('data-id') === '0', 'Expected data-id fallback to index 0');
    assert(card.getAttribute('data-type') === 'movie', 'Expected default type movie');
    assert(card.getAttribute('data-title') === 'Untitled', 'Expected default title Untitled');
    assert(card.getAttribute('data-year') === '—', 'Expected default year —');
    assert(card.getAttribute('data-rating') === 'NR', 'Expected default rating NR');

    const titleEl = card.querySelector('.poster-title');
    assert(titleEl && titleEl.textContent === 'Untitled', 'Expected title element text Untitled');

    // Rating badge should NOT be rendered when rating === 'NR'
    const badge = card.querySelector('.poster-rating-badge');
    assert(!badge, 'NR rating should omit rating badge');
  });

  await check('S1', '03', 'Missing poster/backdrop paths use safe image fallbacks and lazy loading', () => {
    const card = CardFactory.createPosterCard({ id: 101, title: 'No Images' }, 'shelf-test', 0);
    const img = card.querySelector('.poster-media img');
    assert(img, 'Poster img element must exist');
    assert(img.getAttribute('loading') === 'lazy', 'Poster img must have loading="lazy"');
    assert(img.alt === 'No Images', 'Poster img alt text must match title');
    assert(typeof img.onerror === 'function', 'img.onerror handler must be bound');

    // Trigger onerror manually and verify fallback SVG is applied
    img.onerror();
    assert(img.src.indexOf('data:image/svg+xml') === 0, `Expected SVG data URI on error, got ${img.src}`);
    assert(img.src.indexOf('No%20Poster') !== -1 || img.src.indexOf('No Poster') !== -1, 'Fallback SVG must indicate No Poster');
  });

  await check('S1', '04', 'XSS Injection in title (<script>alert(1)</script>) strictly preserved as text, zero script execution', () => {
    const xssPayload = '<script id="injected-script">window.__xss_flag = true;</script><img src="x" onerror="window.__xss_img = true;">';
    const card = CardFactory.createPosterCard({ id: 202, title: xssPayload }, 'shelf-xss', 0);

    const titleEl = card.querySelector('.poster-title');
    assert(titleEl, 'Title element must exist');
    assert(titleEl.textContent === xssPayload, 'textContent must match raw payload verbatim');
    assert(titleEl.innerHTML.indexOf('&lt;script') !== -1, 'Script tags must be HTML-escaped in DOM representation');
    assert(card.querySelectorAll('script').length === 0, 'Zero script tags must be created in card');
    assert(!window.__xss_flag, 'window.__xss_flag must remain undefined');
  });

  await check('S1', '05', 'XSS Injection in ratingDisplay, year, and genres safely treated as pure text nodes', () => {
    const xssItem = {
      id: 303,
      title: 'Safe Title',
      ratingDisplay: '<b id="evil-rating">9.9</b>',
      year: '<script>alert("yr")</script>',
      genres: ['<b id="evil-genre">Action</b>', '<script>alert("g2")</script>']
    };
    const card = CardFactory.createPosterCard(xssItem, 'shelf-xss', 0);

    assert(card.querySelectorAll('#evil-rating, #evil-genre').length === 0, 'No injected HTML elements in DOM');
    const badge = card.querySelector('.poster-rating-badge');
    assert(badge && badge.textContent.includes('<b id="evil-rating">9.9</b>'), 'Rating text contains escaped markup');

    const genreEl = card.querySelector('.poster-genre');
    assert(genreEl && genreEl.textContent.includes('<b id="evil-genre">Action</b>'), 'Genre text contains escaped markup');
  });

  await check('S1', '06', 'Attribute breakout injection payloads ("><b id="breakout">) cannot escape data-* attributes', () => {
    const breakout = '"><b id="breakout">evil</b>';
    const card = CardFactory.createPosterCard({ id: breakout, title: breakout, media_type: breakout }, 'shelf-breakout', 0);

    assert(card.getAttribute('data-id') === breakout, 'data-id holds payload as literal string');
    assert(card.getAttribute('data-title') === breakout, 'data-title holds payload as literal string');
    assert(card.querySelectorAll('#breakout').length === 0, 'Zero breakout elements allowed');
  });

  await check('S1', '07', 'Extreme string length fuzzing (100,000 characters) does not throw or truncate unexpectedly', () => {
    const hugeTitle = 'A'.repeat(100000);
    const hugeGenre = 'G'.repeat(50000);
    const card = CardFactory.createPosterCard({ id: 999, title: hugeTitle, genres: [hugeGenre] }, 'shelf-huge', 0);

    assert(card.getAttribute('data-title').length === 100000, 'Long title preserved in attribute');
    const titleEl = card.querySelector('.poster-title');
    assert(titleEl.textContent.length === 100000, 'Long title preserved in textContent');
  });

  await check('S1', '08', 'Unicode, emoji, RTL, zero-width fuzzing in card fields', () => {
    const unicodeItem = {
      id: 404,
      title: '🎬 Dûñe: Párt Twø \u200B\u200C\u200D 🍿 العربية 🚀',
      year: '2024\u202E',
      genres: ['خيال علمي', 'مغامرة']
    };
    const card = CardFactory.createPosterCard(unicodeItem, 'shelf-unicode', 0);
    const titleEl = card.querySelector('.poster-title');
    assert(titleEl.textContent === unicodeItem.title, 'Unicode title correctly rendered');
    assert(card.getAttribute('data-year') === '2024', 'Year slice correctly handles 4 characters');
  });

  await check('S1', '09', 'createEpisodeCard and createCastCard handle null/undefined and boundary parameters', () => {
    const epCard = CardFactory.createEpisodeCard({ name: 'Pilot', episode_number: 1, runtime: 55 }, 1, 0);
    assert(epCard.getAttribute('data-season') === '1', 'Episode season attribute');
    assert(epCard.getAttribute('data-episode') === '1', 'Episode number attribute');
    assert(epCard.querySelector('.episode-badge').textContent === 'E1', 'Episode badge E1');
    assert(epCard.querySelector('.episode-runtime').textContent === '55m', 'Runtime 55m');

    const castCard = CardFactory.createCastCard({ name: 'Actor Name', character: 'Role Name' }, 0);
    assert(castCard.querySelector('.cast-name').textContent === 'Actor Name', 'Cast name');
    assert(castCard.querySelector('.cast-role').textContent === 'Role Name', 'Cast role');
  });
}

// -----------------------------------------------------------------------------
// SUITE 2: 16:9 Card Proportions (352x198px) & 262px .strip Overflow Stress
// -----------------------------------------------------------------------------
async function runSuite2() {
  console.log(`\n${C.bold}${C.cyan}▶ SUITE 2: 16:9 Card Proportions (352x198px) & 262px .strip Overflow Stress${C.reset}`);

  const tokensCss = fs.readFileSync(path.resolve(__dirname, '../app/css/tokens.css'), 'utf8');
  const componentsCss = fs.readFileSync(path.resolve(__dirname, '../app/css/components.css'), 'utf8');
  const layoutCss = fs.readFileSync(path.resolve(__dirname, '../app/css/layout.css'), 'utf8');

  await check('S2', '01', 'Tokens define exact 16:9 card dimensions (--card-poster-width: 352px, height: 198px)', () => {
    assert(tokensCss.includes('--card-poster-width: 352px;'), 'Must define --card-poster-width: 352px');
    assert(tokensCss.includes('--card-poster-height: 198px;'), 'Must define --card-poster-height: 198px');
    const width = 352;
    const height = 198;
    const ratio = width / height;
    assert(Math.abs(ratio - (16 / 9)) < 0.001, `Aspect ratio must be 16:9 (expected 1.7778, got ${ratio.toFixed(4)})`);
  });

  await check('S2', '02', 'Components CSS enforces 352px card width and 26px margin-right on Home shelves', () => {
    assert(componentsCss.includes('width: 352px;'), 'Card width 352px in components.css');
    assert(componentsCss.includes('margin-right: 26px;'), 'Card margin-right 26px in components.css');
  });

  await check('S2', '03', 'Dual-class architecture: Cards have both Google TV (.card, .pic, .ttl, .chip, .cap) and legacy classes', () => {
    const { CardFactory } = createTestEnvironment();
    const card = CardFactory.createPosterCard({ id: 501, title: 'Interstellar', vote_average: 8.7, year: '2014' }, 'shelf-trending-movies', 0);

    // Card root dual classes
    assert(card.classList.contains('card'), 'Card must have .card class');
    assert(card.classList.contains('card-poster'), 'Card must have .card-poster class');
    assert(card.classList.contains('f'), 'Card must have .f class for spatial focus');

    // Poster media preview surface
    const media = card.querySelector('.pic');
    assert(media, 'Card must have .pic element');
    assert(media.classList.contains('poster-media'), '.pic must have .poster-media class');

    // Title element
    const ttl = card.querySelector('.ttl');
    assert(ttl, 'Card must have .ttl element');
    assert(ttl.classList.contains('poster-title'), '.ttl must have .poster-title class');

    // Rating chip
    const chip = card.querySelector('.chip');
    assert(chip, 'Card must have .chip element');
    assert(chip.classList.contains('poster-badge'), '.chip must have .poster-badge class');

    // Caption meta
    const cap = card.querySelector('.cap');
    assert(cap, 'Card must have .cap element');
    assert(cap.classList.contains('poster-meta'), '.cap must have .poster-meta class');
    assert(cap.classList.contains('poster-info'), '.cap must have .poster-info class');
  });

  await check('S2', '04', '6-Column Catalog Grid cards are strictly scoped to retain 220x330 2:3 proportions', () => {
    assert(componentsCss.includes('.content-grid-6col .card') || componentsCss.includes('.content-grid-6col .card-poster'), 'Must scope catalog grid cards');
    assert(componentsCss.includes('.content-grid-6col .card .pic') || componentsCss.includes('.content-grid-6col .poster-media'), 'Must scope catalog grid pic');
    assert(componentsCss.includes('width: 220px;'), 'Grid width 220px in components.css');
    assert(componentsCss.includes('height: 330px;'), 'Grid height 330px in components.css');
  });

  await check('S2', '05', '.strip vertical geometry budget (262px) comfortably contains 198px card, 1.1x scale and caption', () => {
    assert(componentsCss.includes('height: 262px;'), '.strip must have height: 262px');
    const stripHeight = 262;
    const cardPicHeight = 198;
    const scaledPicHeight = cardPicHeight * 1.1; // 217.8px
    const captionMargin = 14;
    const captionHeight = 24; // font-size 20px with standard line-height
    const focusHaloMargin = 10; // 5px top + 5px bottom
    const totalRequiredHeight = scaledPicHeight + captionMargin + captionHeight + focusHaloMargin;

    assert(totalRequiredHeight <= stripHeight, `Total required height ${totalRequiredHeight.toFixed(1)}px must fit within 262px strip height`);
  });

  await check('S2', '06', 'High-card count stress: 50 cards loaded in shelf verify no structural DOM corruption', () => {
    const { HomeCtrl } = createTestEnvironment();
    const fakeItems = [];
    for (let i = 0; i < 50; i++) {
      fakeItems.push({ id: 1000 + i, title: `Stress Movie ${i}`, vote_average: 7.5 });
    }
    HomeCtrl.renderShelf('shelf-stress', fakeItems, 'movie');

    const shelf = HomeCtrl.container.querySelector('#shelf-stress');
    assert(shelf, 'Stress shelf must exist');
    const rail = shelf.querySelector('.strip');
    assert(rail, 'Rail must have .strip class');

    // Note: HomeCtrl.renderShelf intentionally bounds maxItems to 20 for webOS 1.5GB RAM preservation
    const cards = rail.querySelectorAll('.card');
    assert(cards.length === 20, `Expected capped 20 cards for TV RAM safety, got ${cards.length}`);
    assert(cards[0].getAttribute('data-nav-index') === '0', 'First card index 0');
    assert(cards[19].getAttribute('data-nav-index') === '19', 'Last card index 19');
  });
}

// -----------------------------------------------------------------------------
// SUITE 3: GPU translateX Calculations & Horizontal Scroll Mechanics
// -----------------------------------------------------------------------------
async function runSuite3() {
  console.log(`\n${C.bold}${C.cyan}▶ SUITE 3: GPU translateX Calculations & Horizontal Scroll Mechanics${C.reset}`);
  const { window, HomeCtrl, CardFactory } = createTestEnvironment();

  await check('S3', '01', 'Strip horizontal transition and will-change: transform GPU promotion configured in CSS', () => {
    const componentsCss = fs.readFileSync(path.resolve(__dirname, '../app/css/components.css'), 'utf8');
    assert(componentsCss.includes('will-change: transform;'), '.strip must have will-change: transform');
    assert(componentsCss.includes('transition: transform .35s cubic-bezier(.2, .8, .2, 1);') || componentsCss.includes('transition: transform .35s'), '.strip must have 0.35s cubic-bezier transition');
  });

  await check('S3', '02', 'translateX calculation for card index 0 yields exactly 0px offset', () => {
    const shelf = window.document.createElement('div');
    const strip = window.document.createElement('div');
    strip.className = 'strip shelf-rail';
    const card0 = CardFactory.createPosterCard({ id: 1, title: 'Item 0' }, 'test-shelf', 0);
    // Mock layout offsets in JSDOM
    Object.defineProperty(card0, 'offsetLeft', { value: 0, configurable: true });
    strip.appendChild(card0);
    shelf.appendChild(strip);
    window.document.body.appendChild(shelf);

    HomeCtrl.handleElementFocus(card0);
    assert(strip.style.transform === 'translateX(0px)', `Expected translateX(0px), got ${strip.style.transform}`);
  });

  await check('S3', '03', 'translateX calculation for card index > 0 applies -Math.max(0, offsetLeft - 40)', () => {
    const shelf = window.document.createElement('div');
    const strip = window.document.createElement('div');
    strip.className = 'strip shelf-rail';
    const card1 = CardFactory.createPosterCard({ id: 2, title: 'Item 1' }, 'test-shelf', 1);
    // Card stride = 352px + 26px = 378px
    Object.defineProperty(card1, 'offsetLeft', { value: 378, configurable: true });
    strip.appendChild(card1);
    shelf.appendChild(strip);
    window.document.body.appendChild(shelf);

    HomeCtrl.handleElementFocus(card1);
    // Expected: -(378 - 40) = -338px
    assert(strip.style.transform === 'translateX(-338px)', `Expected translateX(-338px), got ${strip.style.transform}`);

    // Card 5: offsetLeft = 5 * 378 = 1890. Expected: -(1890 - 40) = -1850px
    const card5 = CardFactory.createPosterCard({ id: 6, title: 'Item 5' }, 'test-shelf', 5);
    Object.defineProperty(card5, 'offsetLeft', { value: 1890, configurable: true });
    strip.appendChild(card5);
    HomeCtrl.handleElementFocus(card5);
    assert(strip.style.transform === 'translateX(-1850px)', `Expected translateX(-1850px), got ${strip.style.transform}`);
  });

  await check('S3', '04', 'translateX with non-numeric or missing data-nav-index falls back to colIdx=0 gracefully', () => {
    const strip = window.document.createElement('div');
    strip.className = 'strip shelf-rail';
    const badCard = CardFactory.createPosterCard({ id: 99, title: 'Bad Index' }, 'test-shelf', 'corrupted');
    Object.defineProperty(badCard, 'offsetLeft', { value: 500, configurable: true });
    strip.appendChild(badCard);
    window.document.body.appendChild(strip);

    HomeCtrl.handleElementFocus(badCard);
    // colIdx becomes 0, offsetLeft 500 -> -500px without NaN
    assert(strip.style.transform === 'translateX(-500px)', `Expected translateX(-500px), got ${strip.style.transform}`);
    assert(!strip.style.transform.includes('NaN'), 'Must not produce translateX(NaNpx)');
  });

  await check('S3', '05', 'handleElementFocus resilience when focused element is disconnected or lacks closest()', () => {
    assert.doesNotThrow(() => {
      HomeCtrl.handleElementFocus({});
      HomeCtrl.handleElementFocus(null);
      HomeCtrl.handleElementFocus(undefined);
      HomeCtrl.handleElementFocus(window.document.createTextNode('text'));
    }, 'Must not throw when non-elements or null passed to handleElementFocus');
  });

  await check('S3', '06', 'Rapid bidirectional D-pad focus traversal across 20 cards', () => {
    const strip = window.document.createElement('div');
    strip.className = 'strip shelf-rail';
    const cards = [];
    for (let i = 0; i < 20; i++) {
      const c = CardFactory.createPosterCard({ id: 10 + i, title: `Movie ${i}` }, 'nav-shelf', i);
      Object.defineProperty(c, 'offsetLeft', { value: i * 378, configurable: true });
      strip.appendChild(c);
      cards.push(c);
    }
    window.document.body.appendChild(strip);

    // Forward traverse 0 -> 19
    for (let i = 0; i < 20; i++) {
      HomeCtrl.handleElementFocus(cards[i]);
      const expected = i === 0 ? 0 : -(i * 378 - 40);
      assert(strip.style.transform === `translateX(${expected}px)`, `Card ${i} forward offset mismatch`);
    }

    // Backward traverse 19 -> 0
    for (let i = 19; i >= 0; i--) {
      HomeCtrl.handleElementFocus(cards[i]);
      const expected = i === 0 ? 0 : -(i * 378 - 40);
      assert(strip.style.transform === `translateX(${expected}px)`, `Card ${i} backward offset mismatch`);
    }
  });
}

// -----------------------------------------------------------------------------
// SUITE 4: Carousel Navigation, stepHero & 300ms Debounce Timer under Rapid D-Pad Bursts
// -----------------------------------------------------------------------------
async function runSuite4() {
  console.log(`\n${C.bold}${C.cyan}▶ SUITE 4: Carousel Navigation, stepHero & 300ms Debounce Timer under Rapid D-Pad Bursts${C.reset}`);
  const { window, HomeCtrl } = createTestEnvironment();

  await check('S4', '01', 'Hero presentation elements (#heroSrc, #heroTitle, #heroMeta, #heroSub, #heroBtn, #dots) populated', () => {
    const mockHeroItem = {
      id: 777,
      title: 'Dune: Part Two',
      release_date: '2024-03-01',
      vote_average: 8.6,
      overview: 'Paul Atreides unites with Chani and the Fremen.',
      runtime: 166,
      backdrop_path: '/xOMo8BRK7PfcJv9JCnx7s520dQe.jpg'
    };
    HomeCtrl.heroItems = [mockHeroItem];
    HomeCtrl.heroIdx = 0;
    HomeCtrl.showHero(mockHeroItem);

    const heroSrc = window.document.getElementById('heroSrc');
    assert(heroSrc && heroSrc.textContent.includes('2024') && heroSrc.textContent.includes('2h 46m'), 'heroSrc info');

    const heroTitle = window.document.getElementById('heroTitle');
    assert(heroTitle && heroTitle.textContent === 'Dune: Part Two', 'heroTitle text');

    const heroMeta = window.document.getElementById('heroMeta');
    assert(heroMeta && heroMeta.querySelector('.badge-pill.rating'), 'heroMeta rating pill');
    assert(heroMeta && heroMeta.querySelector('.badge-pill.accent'), 'heroMeta 4K accent badge');

    const heroSub = window.document.getElementById('heroSub');
    assert(heroSub && heroSub.textContent === mockHeroItem.overview, 'heroSub synopsis');

    const heroBtn = window.document.getElementById('heroBtn');
    assert(heroBtn && heroBtn.textContent === 'Open', 'heroBtn Open text');
  });

  await check('S4', '02', 'stepHero(1) forward navigation wraps cyclically across 6 items (0->1->...->5->0)', () => {
    HomeCtrl.heroItems = [
      { id: 1, title: 'H1' }, { id: 2, title: 'H2' }, { id: 3, title: 'H3' },
      { id: 4, title: 'H4' }, { id: 5, title: 'H5' }, { id: 6, title: 'H6' }
    ];
    HomeCtrl.heroIdx = 0;

    for (let step = 1; step <= 6; step++) {
      HomeCtrl.stepHero(1);
      assert(HomeCtrl.heroIdx === step % 6, `After stepHero(1) step ${step}, expected idx ${step % 6}, got ${HomeCtrl.heroIdx}`);
      assert(HomeCtrl.featuredItem.title === `H${(step % 6) + 1}`, 'featuredItem synchronization');
    }
  });

  await check('S4', '03', 'stepHero(-1) backward navigation wraps cyclically from 0 to 5 (0->5->4->...->0)', () => {
    HomeCtrl.heroItems = [
      { id: 1, title: 'H1' }, { id: 2, title: 'H2' }, { id: 3, title: 'H3' },
      { id: 4, title: 'H4' }, { id: 5, title: 'H5' }, { id: 6, title: 'H6' }
    ];
    HomeCtrl.heroIdx = 0;

    HomeCtrl.stepHero(-1);
    assert(HomeCtrl.heroIdx === 5, `Expected index 5 after -1 from 0, got ${HomeCtrl.heroIdx}`);

    HomeCtrl.stepHero(-1);
    assert(HomeCtrl.heroIdx === 4, `Expected index 4 after -1 from 5, got ${HomeCtrl.heroIdx}`);
  });

  await check('S4', '04', 'stepHero with empty or single-item heroItems list does not throw or crash', () => {
    HomeCtrl.heroItems = [];
    HomeCtrl.heroIdx = 0;
    assert.doesNotThrow(() => { HomeCtrl.stepHero(1); }, 'Empty heroItems stepHero(1)');
    assert.doesNotThrow(() => { HomeCtrl.stepHero(-1); }, 'Empty heroItems stepHero(-1)');

    HomeCtrl.heroItems = [{ id: 99, title: 'Solo Hero' }];
    HomeCtrl.heroIdx = 0;
    HomeCtrl.stepHero(1);
    assert(HomeCtrl.heroIdx === 0, 'Single hero item wraps to 0');
  });

  await check('S4', '05', 'Dots indicators synchronize perfectly: active dot has .on class, others do not', () => {
    HomeCtrl.heroItems = [
      { id: 1, title: 'H1' }, { id: 2, title: 'H2' }, { id: 3, title: 'H3' },
      { id: 4, title: 'H4' }, { id: 5, title: 'H5' }, { id: 6, title: 'H6' }
    ];
    HomeCtrl.heroIdx = 2;
    HomeCtrl.showHero();

    const dots = window.document.getElementById('dots');
    assert(dots, '#dots container must exist');
    const dotEls = dots.querySelectorAll('i');
    assert(dotEls.length === 6, `Expected 6 dot elements, found ${dotEls.length}`);
    for (let i = 0; i < dotEls.length; i++) {
      if (i === 2) {
        assert(dotEls[i].classList.contains('on'), `Dot ${i} must have .on class`);
      } else {
        assert(!dotEls[i].classList.contains('on'), `Dot ${i} must NOT have .on class`);
      }
    }
  });

  await check('S4', '06', '300ms Backdrop debounce under rapid D-pad bursts (50 rapid focus events within 50ms)', async () => {
    const bgA = window.document.getElementById('bgA');
    const bgB = window.document.getElementById('bgB');
    assert(bgA && bgB, '#bgA and #bgB must exist in DOM');

    // Simulate 50 rapid D-pad focus events
    for (let i = 0; i < 50; i++) {
      const card = window.document.createElement('div');
      card.className = 'card';
      card.setAttribute('data-backdrop', `http://image.tmdb.org/t/p/w1280/backdrop_${i}.jpg`);
      HomeCtrl.handleElementFocus(card);
    }

    // Immediately after burst (<50ms), background should NOT have updated yet because of 300ms debounce
    assert(!bgA.src.includes('backdrop_49.jpg') && !bgB.src.includes('backdrop_49.jpg'), 'Backdrop must not update immediately during burst');

    // Wait 350ms for debounce timer to fire
    await new Promise(r => setTimeout(r, 350));

    // After 350ms, the FINAL backdrop (backdrop_49) must be set on on-layer
    const activeSrc = bgA.src || bgB.src;
    assert(activeSrc.includes('backdrop_49.jpg'), `Expected final backdrop_49.jpg after debounce, got bgA=${bgA.src}, bgB=${bgB.src}`);
  });

  await check('S4', '07', 'Autoplay idle timer behavior: respects user activity and view state', () => {
    HomeCtrl.idleSince = Date.now();
    HomeCtrl.heroItems = [{ id: 1 }, { id: 2 }];
    HomeCtrl.heroIdx = 0;
    HomeCtrl.startAutoplay();

    // Verify timer instance created
    assert(HomeCtrl.idleTimer !== null, 'idleTimer must be active');

    // Clean up interval
    clearInterval(HomeCtrl.idleTimer);
  });
}

// -----------------------------------------------------------------------------
// SUITE 5: Zero DOM Sinks & Architectural Invariants
// -----------------------------------------------------------------------------
async function runSuite5() {
  console.log(`\n${C.bold}${C.cyan}▶ SUITE 5: Zero DOM Sinks & Architectural Invariants${C.reset}`);

  await check('S5', '01', 'STRICT ZERO .innerHTML = in app/js/views/home.js (excluding comment line 11)', () => {
    const homeContent = fs.readFileSync(path.resolve(__dirname, '../app/js/views/home.js'), 'utf8');
    const lines = homeContent.split('\n');
    const innerHtmlMatches = [];
    lines.forEach((line, idx) => {
      // Allow comment mentions on line 11
      if (line.includes('innerHTML') && !line.trim().startsWith('//') && !line.trim().startsWith('*')) {
        innerHtmlMatches.push({ lineNum: idx + 1, content: line });
      }
    });
    assert(innerHtmlMatches.length === 0, `Forbidden innerHTML assignment found in home.js: ${JSON.stringify(innerHtmlMatches)}`);
  });

  await check('S5', '02', 'STRICT ZERO .outerHTML = in app/js/views/home.js', () => {
    const homeContent = fs.readFileSync(path.resolve(__dirname, '../app/js/views/home.js'), 'utf8');
    const lines = homeContent.split('\n');
    const outerHtmlMatches = [];
    lines.forEach((line, idx) => {
      if (line.includes('outerHTML') && !line.trim().startsWith('//') && !line.trim().startsWith('*')) {
        outerHtmlMatches.push({ lineNum: idx + 1, content: line });
      }
    });
    assert(outerHtmlMatches.length === 0, `Forbidden outerHTML assignment found in home.js: ${JSON.stringify(outerHtmlMatches)}`);
  });

  await check('S5', '03', 'STRICT ZERO document.write or eval() execution in app/js/views/home.js', () => {
    const homeContent = fs.readFileSync(path.resolve(__dirname, '../app/js/views/home.js'), 'utf8');
    assert(!homeContent.includes('document.write'), 'document.write forbidden in home.js');
    assert(!homeContent.includes('eval('), 'eval() forbidden in home.js');
  });

  await check('S5', '04', 'Zero Regression Invariant: SHA-256 byte-for-byte parity across all 8 service files', () => {
    const expectedHashes = {
      'crush.wasm': '40c923580779e2a850fc5ab3f0046be565ed717883cf4547ed3a87de2450bdcf',
      'hls-proxy.js': '8e21e92ee87d81fe9ddf83bbfd3a643afaa3dd1c7e974580664cec06949b53d8',
      'http-client.js': 'ae15c6b8c286bc306ccb6e181ad63fe54f412eda84a8cd0574aa68c2c4703f64',
      'index.js': 'be093dfc3083a8ec243bd0d04db8dfc435322e8f03c01439ed45a42167261e9a',
      'package.json': 'bd99da7eff093729f880518d620ea2790f4faaf024401c283a1c9825984ef5b4',
      'resolver.js': 'e7db23f569e77a099751bec6b8edd45745799ee7a3252e4a9dc0e61a76f1b096',
      'services.json': '5d765f2b34892e6918909c28445057c912ea5b343ad6355941c726525a8e326e',
      'test-service.js': '664173bbaffd5069d6e3c02f7e1d3c74553483116162b8588dfca4ca70da6a03'
    };

    const serviceDir = path.resolve(__dirname, '../services/com.cinejoy.tv.service');
    for (const [file, expectedHash] of Object.entries(expectedHashes)) {
      const fullPath = path.join(serviceDir, file);
      assert(fs.existsSync(fullPath), `Service file missing: ${file}`);
      const fileData = fs.readFileSync(fullPath);
      const actualHash = crypto.createHash('sha256').update(fileData).digest('hex');
      assert(actualHash === expectedHash, `Hash mismatch on ${file}: expected ${expectedHash}, got ${actualHash}`);
    }
  });

  await check('S5', '05', 'Frontend Luna keepalive and proxy resolution cascade preserved in app/js/app.js & config.js', () => {
    const appJs = fs.readFileSync(path.resolve(__dirname, '../app/js/app.js'), 'utf8');
    const configJs = fs.readFileSync(path.resolve(__dirname, '../app/js/config.js'), 'utf8');

    assert(appJs.includes("luna://com.cinejoy.tv.service/keepalive"), 'Luna keepalive URI must exist in app.js');
    assert(configJs.includes("proxyBaseUrl: 'http://127.0.0.1:8088'"), 'Local loopback default in config.js');
    assert(configJs.includes('launchParams.proxyUrl'), 'launchParams override in config.js');
    assert(configJs.includes('urlParams.get'), 'URL query parameter override in config.js');
  });
}

// -----------------------------------------------------------------------------
// MAIN RUNNER
// -----------------------------------------------------------------------------
async function runAll() {
  console.log(`\n${C.bold}${C.magenta}================================================================${C.reset}`);
  console.log(`${C.bold}${C.magenta}  EMPIRICAL ADVERSARIAL CHALLENGER — MILESTONE 2 (R2) SUITE     ${C.reset}`);
  console.log(`${C.bold}${C.magenta}================================================================${C.reset}`);

  await runSuite1();
  await runSuite2();
  await runSuite3();
  await runSuite4();
  await runSuite5();

  console.log(`\n${C.bold}================================================================${C.reset}`);
  console.log(`${C.bold}► ADVERSARIAL CHALLENGER SUMMARY${C.reset}`);
  console.log(`----------------------------------------------------------------`);
  console.log(`  Total Checks:  ${totalChecks}`);
  console.log(`  Passed Checks: ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks: ${failedChecks > 0 ? C.red + failedChecks + C.reset : C.green + '0' + C.reset}`);
  console.log(`----------------------------------------------------------------`);

  if (failedChecks > 0) {
    console.log(`\n${C.bold}${C.red}VERDICT: REJECT (${failedChecks} defects discovered)${C.reset}\n`);
    failureDetails.forEach(f => {
      console.log(`  - ${f.label}: ${f.error}`);
    });
    process.exit(1);
  } else {
    console.log(`\n${C.bold}${C.green}VERDICT: APPROVE (100% EMPIRICAL CHECKS PASSED)${C.reset}\n`);
    process.exit(0);
  }
}

runAll().catch(err => {
  console.error('Fatal execution error:', err);
  process.exit(1);
});

