await check('S2', '05', '.strip vertical geometry budget (262px) comfortably contains 198px card, 1.1x scale and caption', () => {
  assert(componentsCss.includes('height: 262px;'), '.strip must have height: 262px');
  const stripHeight = 262;
  const cardPicHeight = 198;
  const captionMargin = 14;
  const captionHeight = 24; // font-size 20px with standard line-height
  const layoutHeight = cardPicHeight + captionMargin + captionHeight; // 236px

  // Transform scale(1.1) scales about center (50% 50%): top expands by 9.9px, bottom expands by 9.9px
  const topExpansion = (cardPicHeight * 0.1) / 2; // 9.9px
  const visualSpan = layoutHeight + topExpansion; // 245.9px

  assert(layoutHeight <= stripHeight, `Layout height ${layoutHeight}px must fit within 262px strip height`);
  assert(visualSpan <= stripHeight, `Total visual span ${visualSpan.toFixed(1)}px must fit within 262px strip height`);
});

